import fs from "fs";
import path from "path";

const CORE_B64 = "";

const {
  PUBLIC_TABLES,
  splitSqlStatements,
  executeStatements,
  countPublic,
  writeImportLog,
} = await import("./run-pg-sql.mjs");

const markerDir = process.env.IMPORT_MARKER_DIR || "/app/user_data";
const marker = path.join(markerDir, ".core-import-v3");

if (fs.existsSync(marker)) {
  const companies = await countPublic("companies").catch(() => -1);
  if (companies > 0) {
    writeImportLog({ step: "core", skipped: true, companies });
    console.log("import-local-data: marker present, skip");
    process.exit(0);
  }
  console.log("import-local-data: marker present but companies empty, re-import");
}

const sql = Buffer.from(CORE_B64, "base64").toString("utf8");
const inserts = splitSqlStatements(sql);
const statements = [
  "SET client_encoding = 'UTF8'",
  "SET search_path = public",
  `TRUNCATE TABLE ${PUBLIC_TABLES.map((t) => "public." + t).join(", ")} CASCADE`,
  ...inserts,
];

console.log("import-local-data: executing core SQL", inserts.length, "inserts");
try {
  await executeStatements(statements);
} catch (err) {
  writeImportLog({
    step: "core",
    ok: false,
    error: String(err?.message || err).slice(0, 400),
  });
  throw err;
}

const companies = await countPublic("companies");
const users = await countPublic("users");
const projects = await countPublic("allocation_projects");
writeImportLog({ step: "core", ok: true, companies, users, projects });
if (companies === 0) {
  throw new Error("core import finished but companies=0");
}

try {
  fs.mkdirSync(markerDir, { recursive: true });
  fs.writeFileSync(marker, new Date().toISOString());
} catch (err) {
  console.error("import-local-data: could not write marker", err);
}
console.log("import-local-data: core import done", { companies, users, projects });
